import {VoyageDataService} from './service.mjs';
import {CandidateRoutePlanner} from './candidates.mjs';
import {VoyageStudyController} from './controller.mjs';
import {voyageMessage as message} from './messages.mjs';
import {SPECIES} from '../science/catalog.mjs';
import {ACOUSTIC_SOURCE,ACOUSTIC_EVIDENCE} from './acoustics.mjs';
const root=document.getElementById('page-voyage'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>message(k,I18n.language),fmt=(v,d=2)=>Number.isFinite(v)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:d}).format(v):'—',date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString(I18n.locale,{timeZone:'UTC',dateStyle:'medium',timeStyle:'short'})+' UTC':'—';
const fuel=window.WAFuel,science=window.WAScience,service=new VoyageDataService(science),planner=new CandidateRoutePlanner();
let selectedId=null,map=null,mapGroup=null,notice='',formValues={},lastState=null;
const controller=new VoyageStudyController({planner,service,ecologicalModels:science.ecologicalModels,onChange:state=>{lastState=state;if(state.status==='complete')selectedId=state.ranking?.recommendedId||state.results.find(r=>r.status==='computed')?.id||null;renderResults();}});
const input=(key,label,{type='number',value='',min=null,max=null,required=false}={})=>`<label class="voyage-field"><span>${esc(t(label))}</span><input name="${key}" id="vs-${key}" type="${type}" ${type==='number'?'step="any"':''} ${required?'required':''} ${min!==null?`min="${min}"`:''} ${max!==null?`max="${max}"`:''} value="${esc(formValues[key]??value)}"></label>`;
const option=(v,label,current)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(t(label))}</option>`;
const select=(key,label,items,current)=>`<label class="voyage-field"><span>${esc(t(label))}</span><select name="${key}" id="vs-${key}">${items.map(([v,l])=>option(v,l,formValues[key]??current)).join('')}</select></label>`;
const checked=(key,fallback=false)=>formValues[key]??fallback?'checked':'';
function preserveForm(){const form=root.querySelector('form');if(!form)return;formValues=Object.fromEntries([...form.elements].filter(e=>e.name).map(e=>[e.name,e.type==='checkbox'?e.checked:e.value]));}
function render(){preserveForm();map?.remove();map=null;const profiles=fuel.repository.list(),p=fuel.repository.selected(),baseline=window.WALegacy.getPlannedRoute();if(p&&formValues.profileId!==p.id){formValues.profileId=p.id;formValues.speed=p.plannedSpeedKnots;formValues.currency=p.prices?.[0]?.currency||'USD';}root.innerHTML=`<header class="voyage-heading"><div><span class="voyage-kicker">W-ALERTER / ${esc(t('research'))}</span><h1>${esc(t('title'))}</h1><p>${esc(t('intro'))}</p></div><div class="voyage-heading-links"><a href="#route">${esc(t('route'))} ↗</a><a href="#fuel">${esc(t('profiles'))} ↗</a></div></header><div class="voyage-layout"><aside class="voyage-controls"><form id="voyage-form"><h2>${esc(t('setup'))}</h2>${!baseline?`<p class="voyage-setup-note">${esc(t('routeNeeded'))}</p>`:`<div class="voyage-route-summary"><span>A* ·16</span><strong>${fmt(baseline.totalNM)} NM</strong><small>${baseline.inputWaypoints.length} ${esc(t('route'))}</small></div>`}${!p?`<p class="voyage-setup-note">${esc(t('profileNeeded'))}</p>`:''}<label class="voyage-field"><span>${esc(t('profile'))}</span><select name="profileId" id="vs-profileId" required><option value="">—</option>${profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===fuel.repository.selected()?.id?'selected':''}>${esc(p.name)} · v${p.version}</option>`).join('')}</select></label>${input('departure','departure',{type:'datetime-local',required:true})}${input('speed','speed',{value:p?.plannedSpeedKnots??'',min:0,required:true})}${input('altSpeed','altSpeed',{min:0})}${input('deadline','deadline',{type:'datetime-local'})}${select('currentMode','currentMode',[['monthly-currents','currents'],['still-water','still']],'monthly-currents')}<p class="voyage-form-help">${esc(t('currentNote'))}</p>${select('mode','objective',['fastest','emissions','cost','wildlife','balance'].map(k=>[k,k]),'fastest')}<div id="voyage-weights"><p class="voyage-form-help">${esc(t('weightNote'))}</p>${input('weightTime','time',{min:0})}${input('weightCo2','co2',{min:0})}${input('weightCost','declaredCost',{min:0})}</div><label class="voyage-field"><span>${esc(t('target'))}</span><select name="speciesId">${SPECIES.map(s=>`<option value="${s.id}" ${formValues.speciesId===s.id?'selected':''}>${esc(s.scientificName)}</option>`).join('')}</select></label><label class="voyage-check"><input name="alternatives" type="checkbox" ${checked('alternatives',true)}><span>${esc(t('alternatives'))}</span></label><details class="voyage-settings"><summary>${esc(t('economics'))}</summary>${input('currency','currency',{type:'text',value:p?.prices?.[0]?.currency||'USD'})}${input('dailyRate','dailyRate',{min:0})}<label class="voyage-check"><input name="rateAck" type="checkbox" ${checked('rateAck')}><span>${esc(t('rateAck'))}</span></label>${input('fee','fee',{min:0})}${input('feeSource','feeSource',{type:'text'})}${input('carbon','carbon',{min:0})}<p class="voyage-form-help">${esc(t('costNote'))}</p>${input('voyages','voyages',{min:0})}${input('fleet','fleet',{min:1})}${select('basis','basis',[['completed-or-planned','planned'],['theoretical-capacity','capacity']],'completed-or-planned')}${input('utilization','utilization',{min:0,max:1})}<p class="voyage-form-help">${esc(t('annualNote'))}</p></details><button type="submit" class="btn primary full" id="voyage-submit" ${!baseline||!p?'disabled':''}>${esc(t('calculate'))} →</button><button type="button" class="btn secondary full" data-voyage-action="cancel" hidden>${esc(t('cancel'))}</button><p class="voyage-form-help">${esc(t('bounded'))}</p><p class="voyage-form-error" id="voyage-form-error" role="status">${esc(notice)}</p></form></aside><div class="voyage-results" id="voyage-results" aria-live="polite"></div></div><p class="voyage-footer">${esc(t('researchOnly'))}</p>`;toggleControls();renderResults();updateLinks();}
function toggleControls(){root.querySelector('#voyage-weights').hidden=root.querySelector('#vs-mode').value!=='balance';const utilization=root.querySelector('[name=utilization]');utilization.disabled=root.querySelector('#vs-basis').value!=='theoretical-capacity';}
const label=r=>`${t(r.name||'baseline')} · ${fmt(r.speedKnots??r.totals?.stwKnots)} kn`;
function reason(r){const key=r?.reason||'blocked';return t(key)===key?t('blocked'):t(key);}
function card(title,value,unit='',detail=''){return `<article class="voyage-metric"><span>${esc(t(title))}</span><strong>${esc(value)}${unit?`<small>${esc(unit)}</small>`:''}</strong>${detail?`<p>${esc(detail)}</p>`:''}</article>`;}
function renderResults(){const container=root.querySelector('#voyage-results');if(!container)return;map?.remove();map=null;const s=controller.state,submit=root.querySelector('#voyage-submit'),cancel=root.querySelector('[data-voyage-action=cancel]');submit.disabled=s.status==='calculating'||!window.WALegacy.getPlannedRoute()||!fuel.repository.selected();cancel.hidden=s.status!=='calculating';
 if(s.status==='calculating'){container.innerHTML=`<div class="voyage-empty"><span class="voyage-progress-dot"></span><h2>${esc(t('calculating'))}</h2><progress max="1" ${s.progress!=null?`value="${s.progress}"`:''}></progress><p>${esc(t('bounded'))}</p></div>`;return;}
 if(s.status!=='complete'){container.innerHTML=`<div class="voyage-empty"><div class="voyage-empty-symbol">↗</div><h2>${esc(t(s.status==='blocked'?'blocked':'results'))}</h2><p>${esc(s.status==='blocked'?reason(s):t('empty'))}</p><div class="voyage-empty-links"><a href="#route">${esc(t('route'))} ↗</a><a href="#fuel">${esc(t('profiles'))} ↗</a></div></div>`;return;}
 const r=s.results.find(r=>r.id===selectedId)||s.results.find(r=>r.status==='computed'),baseline=s.results.find(r=>r.id==='baseline'),c=r?s.comparisons[r.id]:null;
 const head=`<div class="voyage-result-heading"><div><span class="voyage-kicker">${esc(t('research'))}</span><h2>${esc(t('results'))}</h2></div><button class="btn secondary compact" data-voyage-action="export">${esc(t('export'))} ↓</button></div><p class="voyage-limit">${esc(t('limit'))}</p>`;
 const table=`<section class="voyage-section"><h3>${esc(t('tested'))} · ${s.results.length}</h3><div class="voyage-table-wrap"><table><thead><tr><th>${esc(t('route'))}</th><th>${esc(t('time'))} (h)</th><th>${esc(t('fuel'))} (t)</th><th>CO₂ (t)</th><th>${esc(t('declaredCost'))}</th></tr></thead><tbody>${s.results.map(a=>`<tr class="${a.id===r?.id?'is-selected':''}"><th><button data-voyage-select="${esc(a.id)}">${esc(label(a))}${s.ranking?.recommendedId===a.id?`<small>${esc(t('best'))}</small>`:''}</button>${a.status!=='computed'?`<small>${esc(reason(a))}</small>`:''}</th><td>${fmt(a.totals?.durationHours)}</td><td>${fmt(a.totals?.fuelTonnes,3)}</td><td>${fmt(a.totals?.co2Tonnes,3)}</td><td>${fmt(a.economics?.amount)} ${esc(a.economics?.currency||'')}</td></tr>`).join('')}</tbody></table></div>${s.ranking?.status==='blocked'?`<p class="voyage-state-note">${esc(reason(s.ranking))}</p>`:`<p class="voyage-form-help">${esc(t(s.ranking.recommendedId==='baseline'?'noAdvantage':'explain'))}</p>`}${s.skipped?.length?`<details><summary>${esc(t('skipped'))} · ${s.skipped.length}</summary><ul>${s.skipped.map(x=>`<li>${esc(t(x.id))} · <code>${esc(x.reason)}</code></li>`).join('')}</ul></details>`:''}</section>`;
 if(!r||r.status!=='computed'){const a=s.results.find(a=>a.id===selectedId)||s.results[0];container.innerHTML=head+table+`<div class="voyage-empty"><h3>${esc(reason(a))}</h3>${a?.at?`<p>${fmt(a.at.latitude,5)} / ${fmt(a.at.longitude,5)} · ${esc(date(a.at.date))}</p>`:''}<details><summary>${esc(t('evidence'))}</summary><code>${esc(a?.reason)} · ${esc(a?.sourceStatus||'')}</code></details></div>`;return;}
 const benefit=c?.status==='compared'?c.netVoyageBenefit.benefit:null,chosenCurrency=r.economics.currency||'',sources=r.provenance.sourceRecords;
 container.innerHTML=head+`<div class="voyage-selected-label"><strong>${esc(label(r))}</strong><span>${esc(t(r.scope==='main-engine-only'?'mainOnly':'mainAux'))}</span></div><div class="voyage-metrics">${card('fuel',fmt(r.totals.fuelTonnes,3),'t')}${card('co2',fmt(r.totals.co2Tonnes,3),'t')}${card('time',fmt(r.totals.durationHours),'h',date(r.totals.etaIso))}${card('declaredCost',fmt(r.economics.amount),chosenCurrency)}</div>`+table+`<section class="voyage-section voyage-map-section"><h3>${esc(t('selected'))}</h3><div id="voyage-map" aria-label="${esc(t('route'))}"></div><div class="voyage-map-key">${s.results.filter(a=>a.status==='computed').map(a=>`<button data-voyage-select="${esc(a.id)}" class="${a.id===r.id?'active':''}"><i style="background:${a.id==='baseline'?'#73909c':a.id===r.id?'#087f76':'#c49c59'}"></i>${esc(label(a))}</button>`).join('')}</div><p>${esc(t('bounded'))}</p></section>${comparisonHTML(c,r,baseline)}<section class="voyage-section"><h3>${esc(t('environment'))}</h3><div class="voyage-environment-grid">${['sst','traffic'].map(key=>{const e=r.environment[key];return `<article><span>${esc(t(key))}</span><strong>${e.status==='complete'?fmt(e.mean):'—'} <small>${key==='sst'?'°C':''}</small></strong><p>${esc(t('coverage'))}: ${fmt(e.coverageFraction*100)}%</p>${e.status!=='complete'?`<p>${esc(t('incomplete'))}</p>`:''}</article>`;}).join('')}</div><p>${esc(t('pressureNote'))}</p><p>${esc(t('sampleNote'))}</p></section><section class="voyage-section"><h3>${esc(t('ecology'))} · <i>${esc(SPECIES.find(a=>a.id===s.inputs.speciesId)?.scientificName||s.inputs.speciesId)}</i></h3><div class="voyage-environment-grid">${card('habitat',r.habitat?.status==='computed'?fmt(r.habitat.value):t('unavailable'))}${card('collision',r.collision?.status==='computed'?fmt(r.collision.value):t('unavailable'))}</div><p>${esc(t('modelMissing'))}</p><h4>${esc(t('protection'))}</h4>${r.protection?.status==='computed_supplied_subset_only'?`<strong>${fmt(r.protection.uniqueDistanceNM)} NM</strong><ul>${r.protection.areas.map(a=>`<li>${esc(a.name)} · ${fmt(a.distanceNM)} NM</li>`).join('')}</ul><p>${esc(t('protectionNote'))}</p>`:`<p>${esc(t('protectionMissing'))} <a href="#ocean">↗</a></p>`}</section><section class="voyage-section"><h3>${esc(t('noise'))}</h3>${r.noise.status==='scenario'?`<div class="voyage-environment-grid">${r.noise.bands.map(b=>card(String(b.nominalHz)+' Hz',fmt(b.meanLevelDb),'dB re1µPa²m²')).join('')}</div><p>${esc(t('noiseNote'))}</p>`:`<p>${esc(t('noiseMissing'))} <a href="#fuel">${esc(t('profiles'))} ↗</a></p>`}<p>${esc(t('received'))}</p><a href="${ACOUSTIC_SOURCE.url}" target="_blank" rel="noopener">JOMOPANS-ECHO2021 · CC BY4.0 ↗</a><span class="voyage-source-links"><a href="${ACOUSTIC_EVIDENCE.navison.url}" target="_blank" rel="noopener">EMSA NAVISON June2025-v2 ↗</a><a href="${ACOUSTIC_EVIDENCE.noaa.url}" target="_blank" rel="noopener">NOAA2024-v3 ↗</a></span></section><details class="voyage-section"><summary>${esc(t('evidence'))}</summary><dl class="voyage-audit"><div><dt>SHA-256</dt><dd>${esc(r.provenance.inputSha256)}</dd></div><div><dt>${esc(t('profile'))}</dt><dd>${esc(r.provenance.inputs.profile.name)} · v${r.profileVersion}</dd></div><div><dt>${esc(t('date'))}</dt><dd>${esc(date(r.provenance.calculatedAt))}</dd></div><div><dt>${esc(t('distance'))}</dt><dd>${fmt(r.totals.distanceNM)} NM · R3440.065 NM</dd></div><div><dt>STW / SOG</dt><dd>${fmt(r.totals.stwKnots)} / ${fmt(r.totals.meanSogKnots)} kn</dd></div></dl><div class="voyage-table-wrap"><table><thead><tr><th>${esc(t('source'))}</th><th>${esc(t('date'))}</th><th>${esc(t('quality'))}</th></tr></thead><tbody>${sources.map(a=>`<tr><th>${esc(a.datasetId)}<small>${esc(a.revision)}</small><small class="voyage-hash">${esc(a.source.sha256)}</small></th><td>${esc(a.calendarPeriod||a.time)}<small>${esc(a.units)}</small></td><td>${a.uncertainty?.value!=null?esc(a.uncertainty.value)+' '+esc(a.uncertainty.units):esc(t('unknown'))}</td></tr>`).join('')}</tbody></table></div><p>${esc(t('currentNote'))}</p><details><summary>${esc(t('timeline'))} · ${r.segments.length}</summary><div class="voyage-table-wrap"><table><thead><tr><th>UTC</th><th>NM</th><th>STW / SOG (kn)</th><th>u / v (m/s)</th><th>kW</th><th>${esc(t('fuel'))} (kg)</th></tr></thead><tbody>${r.segments.map(a=>`<tr><th>${esc(date(a.startIso))}</th><td>${fmt(a.distanceNM)}</td><td>${fmt(a.stwKnots)} / ${fmt(a.sogKnots)}</td><td>${a.current?fmt(a.current.u,3)+' / '+fmt(a.current.v,3):'—'}</td><td>${fmt(a.powerKw)}</td><td>${fmt(a.mainFuelKg+(a.auxiliaryFuelKg??0))}</td></tr>`).join('')}</tbody></table></div></details><p><a href="voyage/methodology.md" target="_blank">${esc(t('evidence'))} ↗</a></p></details>`;
 if(document.body.dataset.page==='voyage')drawMap(s,r);
}
function comparisonHTML(c,r,baseline){if(!c||c.status!=='compared')return '';const currency=r.economics.currency||'',metrics=[['fuel',c.fuel,'kg'],['co2',c.co2,'kg'],['time',c.time,'h'],['distance',c.distance,'NM']];return `<section class="voyage-section"><h3>${esc(t('change'))}</h3><div class="voyage-table-wrap"><table><thead><tr><th>${esc(t('metric'))}</th><th>${esc(t('baseline'))}</th><th>${esc(t('selected'))}</th><th>Δ</th></tr></thead><tbody>${metrics.map(([k,v,u])=>`<tr><th>${esc(t(k))} (${u})</th><td>${fmt(v.baseline)}</td><td>${fmt(v.candidate)}</td><td>${v.difference>0?'+':''}${fmt(v.difference)}</td></tr>`).join('')}</tbody></table></div><p>${esc(t('compareNote'))}</p><div class="voyage-metrics voyage-money">${card('benefit',fmt(c.netVoyageBenefit.benefit),currency,t('positiveBenefit'))}${card('annual',fmt(c.annual?.value),currency,t('annualNote'))}</div><details><summary>${esc(t('sensitivity'))}</summary><p>${esc(t('sensitivityNote'))}</p><div class="voyage-table-wrap"><table><thead><tr><th>${esc(t('fuel'))}</th><th>${esc(t('benefit'))} (${esc(currency)})</th></tr></thead><tbody>${c.sensitivity.map(a=>`<tr><th>×${fmt(a.fuelPriceMultiplier)}</th><td>${fmt(a.benefit)}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
function drawMap(s,r){const element=root.querySelector('#voyage-map');if(!element||!window.L)return;map=L.map(element,{scrollWheelZoom:false}).setView([42,-70],5);L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Ocean/World_Ocean_Base/MapServer/tile/{z}/{y}/{x}',{maxZoom:13,attribution:'Esri · GEBCO · NOAA'}).addTo(map);mapGroup=L.featureGroup().addTo(map);for(const a of [...s.results.filter(a=>a.status==='computed'&&a.id!==r.id),r]){let previous=null;const coords=a.route.coordinates.map(([x,y])=>{while(previous!==null&&x-previous>180)x-=360;while(previous!==null&&x-previous< -180)x+=360;previous=x;return [y,x];});L.polyline(coords,{color:a.id==='baseline'?'#73909c':a.id===r.id?'#087f76':'#c49c59',weight:a.id===r.id?4:2,opacity:a.id===r.id?1:.6,dashArray:a.id==='baseline'?'7 6':null}).bindTooltip(esc(label(a))).on('click',()=>{selectedId=a.id;renderResults();}).addTo(mapGroup);}map.fitBounds(mapGroup.getBounds(),{padding:[30,30],maxZoom:9});requestAnimationFrame(()=>map?.invalidateSize());}
function updateLinks(){root.setAttribute('aria-label',t('title'));if(document.body.dataset.page==='voyage')document.title=t('title')+' — W-ALERTER';for(const el of document.querySelectorAll('[data-voyage-link]'))el.textContent=t('title')+' ↗';}
const routeOutput=document.getElementById('routeOutput');if(routeOutput){const link=document.createElement('a');link.href='#voyage';link.className='btn secondary voyage-link';link.dataset.voyageLink='';link.dataset.userContent='';routeOutput.prepend(link);}
root.addEventListener('input',e=>{if(!e.target.closest('form'))return;notice='';controller.invalidate();toggleControls();});
root.addEventListener('change',e=>{if(e.target.id==='vs-profileId'&&e.target.value){preserveForm();try{fuel.repository.select(e.target.value);formValues.speed=fuel.repository.selected().plannedSpeedKnots;render();}catch{notice=t('profileNeeded');}}toggleControls();});
root.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(!form.reportValidity())return;preserveForm();try{const val=key=>form.elements[key].value.trim(),num=key=>val(key)===''?null:Number(val(key)),currency=val('currency').toUpperCase(),iso=key=>val(key)?new Date(val(key)+'Z').toISOString():null,fee=num('fee'),annual=num('voyages')===null&&num('fleet')===null?null:{voyagesPerVessel:num('voyages'),fleetSize:num('fleet'),countBasis:val('basis'),utilization:val('basis')==='theoretical-capacity'?num('utilization'):null};if(!/^[A-Z]{3}$/.test(currency)||fee!==null&&!val('feeSource')||num('dailyRate')!==null&&!form.elements.rateAck.checked)throw Error('invalidInputs');const profile=fuel.repository.list().find(p=>p.id===val('profileId')),baseline=window.WALegacy.getPlannedRoute();if(!profile||!baseline)throw Error('invalidInputs');notice='';root.querySelector('#voyage-form-error').textContent='';controller.update({baseline,profile,departureIso:iso('departure'),arrivalTargetIso:iso('deadline'),stwKnots:num('speed'),alternativeSpeedKnots:num('altSpeed'),currentMode:val('currentMode'),includeAlternatives:form.elements.alternatives.checked,mode:val('mode'),speciesId:val('speciesId'),weights:val('mode')==='balance'?{durationHours:num('weightTime')??0,co2Kg:num('weightCo2')??0,cost:num('weightCost')??0}:null,economics:{currency,dailyNonFuelRate:num('dailyRate'),rateExcludesFuelAndFees:form.elements.rateAck.checked,fees:fee===null?[]:[{amount:fee,category:'user-declared-fixed',currency,source:val('feeSource')}],carbonScenarioPerTonne:num('carbon')},annual});}catch{notice=t('invalidInputs');root.querySelector('#voyage-form-error').textContent=notice;}});
root.addEventListener('click',e=>{const row=e.target.closest('[data-voyage-select]');if(row){selectedId=row.dataset.voyageSelect;renderResults();return;}const action=e.target.closest('[data-voyage-action]')?.dataset.voyageAction;if(action==='cancel')controller.invalidate('analysis_cancelled');if(action==='export'&&controller.state.status==='complete'){const blob=new Blob([JSON.stringify({format:'w-alerter-voyage-study',version:1,exportedAt:new Date().toISOString(),...controller.state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='w-alerter-voyage-study.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}});
for(const name of ['walerter:routechange','walerter:routeplanned'])window.addEventListener(name,()=>{controller.invalidate();if(document.body.dataset.page==='voyage')render();});
fuel.repository.subscribe(()=>{controller.invalidate();if(document.body.dataset.page==='voyage')render();});
window.addEventListener('languagechange',()=>{render();updateLinks();});window.addEventListener('walerter:pagechange',e=>{if(e.detail.page==='voyage')render();});
window.WAVoyage=Object.freeze({service,planner,controller,current:()=>structuredClone(controller.state)});render();
